using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Opt back in to the legacy name so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id property format changed from "EntityType|Key" to just "Key" in EF Core 9.
        // Use IdProperty + HasPartitionKey to keep the old id-synthesis strategy,
        // or set the id shadow property explicitly. Here we opt into the legacy format.
        modelBuilder.Entity<Blog>().HasPartitionKey("__partitionKey");
        modelBuilder.Entity<Blog>().Property<string>("__id")
            .ToJsonProperty("id");
        modelBuilder.Entity<Blog>().HasKey("__id");

        // Breaking change 3: Cosmos DB provider no longer supports sync I/O in EF Core 9.
        // See SyncJob.cs — all calls converted to async equivalents.

        // Breaking change 4: HasIndex() now throws for Cosmos provider in EF Core 9.
        // Indexes are managed by Cosmos DB itself; the EF call has been removed.
        // (was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

