using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1 — Discriminator property renamed "$type" (was "Discriminator").
        // Fix: opt back to the old property name so existing documents are found.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // BREAKING CHANGE 2 — Synthesized JSON "id" no longer includes the discriminator.
        //   EF 8 format: "Blog|1"   →   EF 9 format: "1"
        // Fix: map a concrete property to the JSON "id" so existing docs are matched.
        modelBuilder.Entity<Blog>()
            .Property(b => b.CosmosId)
            .ToJsonProperty("id");
        modelBuilder.Entity<Blog>()
            .HasKey(b => b.CosmosId);

        // BREAKING CHANGE 3 — HasIndex() now throws for the Cosmos provider.
        // Fix: remove the call (Cosmos manages its own indexes).
        // (was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)

        // BREAKING CHANGE 4 — Sync I/O removed (see SyncJob.cs).
    }
}

class Blog
{
    // Stores the Cosmos "id" in the legacy "Discriminator|Key" format, e.g. "Blog|1"
    public string CosmosId { get; set; }
    public string Id { get; set; }
    public string Name { get; set; }
}

