using Microsoft.EntityFrameworkCore;

class SyncJob
{
    // Breaking change 4: Sync I/O (ToList, SaveChanges, etc.) is no longer supported
    // by the Cosmos DB provider in EF Core 9. Use async equivalents.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

